#!/bin/bash
# Generated by GitHub Copilot - Nov-20-2026

# Test Script per la nuova azione SearchRole
# Uso: bash test_commands.sh <token>
# Oppure esportare XSUAA_CLIENT_ID e XSUAA_CLIENT_SECRET e usare --get-token.

set -euo pipefail

SERVICE_URL="https://acea-dev-datasphere-gcp-dev-dsp-scim-handler-srv.cfapps.eu30.hana.ondemand.com"
XSUAA_URL="https://dev-datasphere-gcp.authentication.eu30.hana.ondemand.com/oauth/token"

ROLE_TO_SEARCH="BW_C_IT_0170_AEEN_COCGU"

# Ottiene un token usando credenziali di ambiente, senza stamparle o esporle negli argomenti di curl.
get_token() {
    : "${XSUAA_CLIENT_ID:?Impostare XSUAA_CLIENT_ID nell'ambiente}"
    : "${XSUAA_CLIENT_SECRET:?Impostare XSUAA_CLIENT_SECRET nell'ambiente}"
    echo "🔐 Ottenimento token OAuth2..." >&2
    TOKEN=$(jq -rn '"grant_type=client_credentials&client_id=" + (env.XSUAA_CLIENT_ID | @uri) + "&client_secret=" + (env.XSUAA_CLIENT_SECRET | @uri)' \
        | curl --silent --show-error --fail --max-time 30 -X POST "$XSUAA_URL" \
            -H "Content-Type: application/x-www-form-urlencoded" \
            --data-binary @- \
        | jq -er '.access_token | select(type == "string" and length > 0)') || return 1

    echo "✅ Token ottenuto" >&2
    printf '%s\n' "$TOKEN"
}

# Cerca un ruolo serializzando l'input in JSON, senza interpolazione manuale.
search_role() {
    local token=$1
    local role=$2

    echo ""
    printf '%0.s=' {1..70}; echo
    echo "🔍 Ricerca ruolo: $role"
    printf '%0.s=' {1..70}; echo

    jq -nc --arg role "$role" '{roleValue: $role}' \
        | curl --max-time 30 -X POST "$SERVICE_URL/data/SearchRole" \
            -H "Authorization: Bearer $token" \
            -H "Accept: application/json" \
            -H "Content-Type: application/json" \
            --data-binary @- | jq .
}

# Main
if [[ "${1:-}" == "--get-token" ]]; then
    TOKEN=$(get_token)
else
    TOKEN="${1:-}"
    if [[ -z "$TOKEN" ]]; then
        echo "❌ Uso: $0 <token> oppure $0 --get-token"
        echo ""
        echo "Per ottenere il token automaticamente:"
        echo "  bash $0 --get-token"
        echo ""
        echo "Oppure con un token fornito:"
        echo "  bash $0 <access_token>"
        exit 1
    fi
fi

# Test endpoint 1: Leggi tutti i ruoli (RolesVH)
echo ""
printf '%0.s=' {1..70}; echo
echo "📊 Test 1: Leggi tutti i ruoli (RolesVH)"
printf '%0.s=' {1..70}; echo
curl -s --max-time 30 "$SERVICE_URL/data/RolesVH?%24top=10" \
    -H "Authorization: Bearer $TOKEN" \
    -H "Accept: application/json" | jq .

# Test endpoint 2: Cerca il ruolo specifico
search_role "$TOKEN" "$ROLE_TO_SEARCH"

# Test endpoint 3: Cerca un altro ruolo di prova
echo ""
printf '%0.s=' {1..70}; echo
echo "🧪 Test 2: Ricerca ruolo inesistente"
printf '%0.s=' {1..70}; echo
search_role "$TOKEN" "ROLE_NON_ESISTENTE_12345"

echo ""
printf '%0.s=' {1..70}; echo
echo "✅ Test completato"
printf '%0.s=' {1..70}; echo